#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Issue #208: Provider Secrets. Super-admins enter third-party keys in the Back
# Office (/admin/cles); the app encrypts them under the master keys in
# SECRETS_MASTER_KEYS (ADR-0020, docs/ops/provider-secrets.md). The code is
# deployed by CI; only a human can create the master keys and put them where the
# staging and production containers read them (AWS Secrets Manager, eu-west-3).
# Use a different key for local, staging and production. Never paste a key in a
# ticket, a chat or a commit.

TOTAL_STAGES=5

# A master key entry: version 1, 32 random bytes in base64.
new_master_key() { printf '1:%s' "$(openssl rand -base64 32)"; }

banner "Provider Secrets: master keys for the Clés section (#208)"

stage "Local development: a master key in .env"
say "The web app and the worker read SECRETS_MASTER_KEYS from the repo-root .env."
say "Without it, the Clés section shows its keys but cannot save one."
if ! command -v openssl >/dev/null 2>&1; then
  warn "openssl is not installed: install it, or paste a key you made elsewhere (32 random bytes, base64)."
  ask_secret SECRETS_MASTER_KEYS "SECRETS_MASTER_KEYS (1:<base64 key>)"
  write_env SECRETS_MASTER_KEYS "$SECRETS_MASTER_KEYS"
elif [[ -n "$(_existing SECRETS_MASTER_KEYS)" ]]; then
  note "SECRETS_MASTER_KEYS is already set in $ENV_FILE: kept (replacing it would leave saved keys unreadable)."
else
  write_env SECRETS_MASTER_KEYS "$(new_master_key)"
  say "A new master key (version 1) is in $ENV_FILE. Restart npm run dev and the worker."
fi
pause

stage "Staging: store a master key in AWS Secrets Manager"
say "Make a key for staging only, in a terminal of your own (it is not shown here):"
note "  printf '1:%s\\n' \"\$(openssl rand -base64 32)\""
open_url "https://eu-west-3.console.aws.amazon.com/secretsmanager/listsecrets?region=eu-west-3"
step "Open the staging app secret the ECS tasks read (the one holding DATABASE_URL and AUTH_SECRET)."
step "Retrieve secret value → Edit → Add row: key SECRETS_MASTER_KEYS, value the line you made (1:…)."
step "Save. Keep no other copy of it next to a database snapshot."
note "Not sure which secret it is? The staging task definitions' \"secrets\" list names it (next stage)."
pause "Press Enter once SECRETS_MASTER_KEYS is in the staging secret."

stage "Staging: give it to the web app and the worker"
open_url "https://eu-west-3.console.aws.amazon.com/ecs/v2/task-definitions?region=eu-west-3"
step "Open the staging web app task definition → Create new revision."
step "Container → Environment variables → Add: SECRETS_MASTER_KEYS, ValueFrom, <secret ARN>:SECRETS_MASTER_KEYS::"
step "Do the same for the staging worker task definition: both must get the same list."
step "Update both staging services to the new revisions (Force new deployment)."
note "The worker re-encrypts every saved key under the newest master key when it starts."
pause "Press Enter once both staging services run the new revisions."

stage "Staging: check the Clés section"
open_url "https://github.com/fnconsult/jobhub/blob/main/docs/ops/provider-secrets.md"
step "Sign in to staging as a super-admin and open Back office → Plateforme → Clés (/admin/cles)."
say "Expected: no \"Enregistrement désactivé : SECRETS_MASTER_KEYS…\" notice; every key shows its source."
step "Optional: replace a key you can test cheaply (e.g. MISTRAL_API_KEY with the same value); the test must pass."
step "Then open the Journal: the entry says \"Remplacement\", with no value."
if confirm "Does staging save and test keys in Clés?"; then
  say "Staging is ready."
else
  SKIPPED+=("Staging Clés check failed: read the web app's CloudWatch log ([provider-secrets] lines, never values)")
  warn "Check the web app log for [provider-secrets] lines, then run this stage again."
fi
pause

stage "Production: the same, with its own key"
warn "Use a new key: never staging's. Losing it makes every key saved in Clés unreadable (env stands in)."
open_url "https://eu-west-3.console.aws.amazon.com/secretsmanager/listsecrets?region=eu-west-3"
step "Add SECRETS_MASTER_KEYS (1:<new key>) to the production app secret."
step "Add it to the production web app and worker task definitions, as for staging, and deploy both."
step "Store a sealed copy of the key in the team's password manager (not with database backups)."
step "Check /admin/cles in production as a super-admin, as for staging."
note "Rotating it later: docs/ops/provider-secrets.md (add 2:<key>, deploy, check, drop 1:)."
pause "Press Enter once production is done."

finish
